policies.inbound:



  {{ExpectedAudience}}
  {{TenantId}}



    {"error":"Budget API supports POST /deployments/{id}/chat/completions only."}




<set-variable name="budgetRequestBody" value="@(context.Request.Body.As(preserveContent: true))" />
@(JObject.Parse((string)context.Variables["budgetRequestBody"]).ToString())




  @("{{ContainerAppUrl}}/api/precheck/" + Uri.EscapeDataString((string)context.Variables["budgetClient"]) + "/" + Uri.EscapeDataString((string)context.Variables["budgetTenant"]) + "?deploymentId=" + Uri.EscapeDataString((string)context.Variables["budgetDeployment"]) + "&apiId=" + Uri.EscapeDataString(context.Api.Id) + "&operationId=" + Uri.EscapeDataString(context.Operation.Id))
  GET
  @("Bearer " + (string)context.Variables["budgetEngineToken"])









<set-variable name="budgetBackendUrl" value="@(((IResponse)context.Variables["budgetPrecheck"]).Body.As(preserveContent: true)["backendUrl"]?.ToString() ?? "")" />
<set-variable name="budgetActualDeployment" value="@{
  var routed = ((IResponse)context.Variables["budgetPrecheck"]).Body.As(preserveContent: true)["routedDeployment"]?.ToString();
  return string.IsNullOrEmpty(routed) ? (string)context.Variables["budgetDeployment"] : routed;
}" />





  {"error":"The approved model backend could not be resolved."}


  @("{{ContainerAppUrl}}/api/budgets/" + (string)context.Variables["budgetTenant"] + "/reserve")
  POST
  @("Bearer " + (string)context.Variables["budgetEngineToken"])
  application/json
  @{
    var jwt = (Jwt)context.Variables["budgetJwt"];
    var delegated = !string.IsNullOrEmpty(jwt.Claims.GetValueOrDefault("scp", ""));
    var groups = jwt.Claims.ContainsKey("groups") ? jwt.Claims["groups"] : new string[0];
    var complete = !delegated || (jwt.Claims.ContainsKey("groups") && !jwt.Claims.ContainsKey("hasgroups") && !jwt.Claims.ContainsKey("_claim_names"));
    return new JObject(
      new JProperty("requestId", context.RequestId.ToString()),
      new JProperty("clientAppId", (string)context.Variables["budgetClient"]),
      new JProperty("userId", delegated ? jwt.Claims.GetValueOrDefault("oid", "") : null),
      new JProperty("groupIds", new JArray(groups)),
      new JProperty("groupsComplete", complete),
      new JProperty("deploymentId", (string)context.Variables["budgetActualDeployment"]),
      new JProperty("requestBody", JObject.Parse((string)context.Variables["budgetRequestBody"]))).ToString();
  }
